-- Migration 0010: seed Privacy Policy and Terms of Use page content
-- These are initial drafts; administrators can edit and publish via the CMS.

-- The pages table originally only has a partial unique index on slug WHERE published.
-- Add a full unique constraint so ON CONFLICT (slug) works for upserts.
ALTER TABLE public.pages ADD CONSTRAINT pages_slug_unique UNIQUE (slug);

INSERT INTO public.pages(slug, title, body, published, seo_title, seo_description)
VALUES
(
  'privacy',
  'Privacy Policy',
  E'Effective date: 1 January 2025\n\nAVIV Safe Place ("AVIV", "we", "us") is committed to protecting your privacy. This Privacy Policy explains what information we collect, how we use it, and your rights in relation to that information. By using our website or services you agree to the practices described here.\n\n1. Who We Are\n\nAVIV Safe Place is a counselling and family restoration service based in Nigeria. Our website is located at the domain where you found this policy. You can contact us at the email address listed on our Contact page.\n\n2. Information We Collect\n\nWe collect information in the following ways:\n\na) Contact Enquiries: When you submit the contact form, we collect your name, email address, subject line, and the content of your message. We do not ask for and you should not include sensitive counselling details in the form.\n\nb) Session Bookings: When you request a counselling session, we collect your name, email address, phone number (optional), the service type, and your requested appointment time. We also generate a private, randomly-issued link for you to manage your booking. No payment information is handled directly by our website.\n\nc) Automatically Collected Data: Our server may log standard request metadata (such as browser type and approximate request origin) for security and rate-limiting purposes. Raw IP addresses are hashed immediately and not stored in identifiable form.\n\nd) Cookies and Local Storage: Our website uses browser local storage solely to maintain your authenticated session if you are an authorised administrator. We do not use advertising or third-party tracking cookies.\n\n3. How We Use Your Information\n\nWe use the information we collect to:\n- Respond to your enquiries and communicate with you about your booking.\n- Arrange and confirm counselling appointments.\n- Prevent abuse and protect the security of our systems through rate limiting.\n- Fulfil our legal obligations.\n\nWe do not sell, rent, or share your personal information with third parties for marketing purposes.\n\n4. Legal Basis for Processing (NDPR)\n\nWe process your personal data on the following bases under the Nigeria Data Protection Regulation (NDPR) and its 2023 Act:\n- Consent: where you have voluntarily submitted a contact form or booking request.\n- Contractual necessity: to fulfil a counselling appointment you have requested.\n- Legitimate interests: to protect our systems from abuse and ensure service continuity.\n\n5. Data Retention\n\nContact enquiries are retained for up to twelve months from receipt and then deleted, unless an ongoing relationship or legal obligation requires longer retention. Booking records are retained for up to three years for operational and auditing purposes. You may request deletion at any time (see Section 8).\n\n6. Data Security\n\nWe take reasonable technical and organisational measures to protect your information, including encrypted data transmission (HTTPS), hashed rate-limit identifiers, row-level security on our database, and access controls that restrict administrator access to authorised personnel only. No system is completely secure; if you believe your data has been compromised, please contact us immediately.\n\n7. Third-Party Services\n\nOur website uses Supabase (hosted in the European Union) to store data. Supabase processes data under its own privacy policy and is subject to EU data protection standards. Payment processing will be provided by Paystack in a future release; this policy will be updated at that time. We do not embed social media trackers or advertising pixels on our website.\n\n8. Your Rights\n\nUnder the NDPR and applicable law you have the right to:\n- Access the personal information we hold about you.\n- Correct inaccurate information.\n- Request deletion of your information (right to erasure), subject to our legal obligations.\n- Object to or restrict our processing of your data.\n- Receive a copy of your data in a portable format.\n- Lodge a complaint with the Nigeria Data Protection Commission (NDPC).\n\nTo exercise any of these rights, please contact us using the details on our Contact page. We will respond within 30 days.\n\n9. Children\n\nOur services are intended for adults. We do not knowingly collect personal information from anyone under the age of 18. If you believe a minor has submitted information to us, please contact us so we can delete it.\n\n10. Changes to This Policy\n\nWe may update this Privacy Policy from time to time. We will post the updated version on this page with a new effective date. Continued use of our website after changes are posted constitutes acceptance of the revised policy.\n\n11. Contact Us\n\nIf you have any questions about this Privacy Policy, please reach out using the details on our Contact page.',
  true,
  'Privacy Policy — AVIV Safe Place',
  'How AVIV Safe Place handles your personal information, bookings and enquiries.'
),
(
  'terms',
  'Terms of Use',
  E'Effective date: 1 January 2025\n\nPlease read these Terms of Use carefully before using the AVIV Safe Place website. By accessing or using our website, you agree to be bound by these terms.\n\n1. About AVIV Safe Place\n\nAVIV Safe Place provides compassionate counselling and family restoration services in Nigeria. Our website allows visitors to learn about our services, submit general enquiries, and request counselling appointments. Nothing on this website constitutes professional medical, legal, financial or emergency advice.\n\n2. Use of This Website\n\na) You may use this website for lawful personal purposes only.\nb) You must not use this website in any way that violates applicable law, infringes the rights of others, or disrupts the operation of our services.\nc) You must not attempt to gain unauthorised access to any part of this website, our servers, or related systems.\nd) You must not submit false, misleading, or harmful content through any form on this website.\ne) Automated scraping, crawling, or data harvesting without our written consent is prohibited.\n\n3. Counselling Services and Booking\n\na) Requesting a booking through this website does not guarantee an appointment. All appointments require confirmation by AVIV after payment is verified.\nb) We hold your requested time for 30 minutes following a booking request. If payment is not completed within that window, the hold lapses and the time is released.\nc) Online payment is not available in the current phase. AVIV will communicate payment arrangements directly.\nd) AVIV reserves the right to decline or cancel any booking at its sole discretion.\ne) Counselling services are provided to adults (18 and over). Minors may only access services with the written consent of a parent or legal guardian.\n\n4. Cancellation and Rescheduling\n\nOur full cancellation and rescheduling policy is set out on the Cancellation & Rescheduling page. Key terms are:\n- No refunds are provided except where required by Nigerian law.\n- Rescheduling requests must be submitted within three days of the originally scheduled appointment.\n- Failure to submit a timely rescheduling request will result in cancellation without refund.\n\n5. Intellectual Property\n\nAll content on this website — including text, images, logos, and design elements — is owned by or licensed to AVIV Safe Place and is protected by applicable intellectual property law. You may not reproduce, distribute, or create derivative works from our content without our prior written consent.\n\n6. Privacy\n\nYour use of this website is also governed by our Privacy Policy, which is incorporated into these Terms by reference.\n\n7. Disclaimers\n\na) This website and its content are provided "as is" without warranties of any kind, express or implied.\nb) AVIV Safe Place makes no warranty that the website will be uninterrupted, error-free, or free of viruses or harmful components.\nc) Information on this website is for general informational purposes. It does not constitute professional counselling, medical or psychological advice, and should not be relied upon as such.\nd) In a mental health or safety emergency, please contact your local emergency services immediately. This website is not an emergency service.\n\n8. Limitation of Liability\n\nTo the fullest extent permitted by Nigerian law, AVIV Safe Place shall not be liable for any indirect, incidental, special, or consequential damages arising from your use of — or inability to use — this website or our services, even if we have been advised of the possibility of such damages.\n\n9. Third-Party Links\n\nThis website may contain links to third-party websites. We do not control those websites and are not responsible for their content or privacy practices. Linking to a third-party website does not constitute an endorsement.\n\n10. Governing Law\n\nThese Terms are governed by the laws of the Federal Republic of Nigeria. Any dispute arising from these Terms shall be subject to the jurisdiction of Nigerian courts, with an initial attempt at amicable resolution.\n\n11. Changes to These Terms\n\nWe may revise these Terms at any time by posting an updated version on this page. Your continued use of the website after changes are posted constitutes acceptance of the revised Terms.\n\n12. Contact\n\nFor questions about these Terms, please use the contact details on our Contact page.',
  true,
  'Terms of Use — AVIV Safe Place',
  'Terms and conditions for using the AVIV Safe Place website and counselling services.'
)
ON CONFLICT (slug) DO UPDATE
  SET title           = EXCLUDED.title,
      body            = EXCLUDED.body,
      seo_title       = EXCLUDED.seo_title,
      seo_description = EXCLUDED.seo_description,
      published       = EXCLUDED.published,
      updated_at      = now()
WHERE pages.body = '' OR length(pages.body) < 100;
